    setObjectName("instrumentPanel");setMinimumHeight(350);
    auto* layout=new QVBoxLayout(this);auto* controls=new QHBoxLayout;selection_=new QComboBox;selection_->setObjectName("instrumentSelector");controls->addWidget(selection_,1);
    timebase_=new QDoubleSpinBox;timebase_->setObjectName("instrumentTimebase");timebase_->setDecimals(2);timebase_->setRange(.01,1000);timebase_->setValue(1);timebase_->setSuffix(" ms/div");controls->addWidget(timebase_);
    scale_=new QDoubleSpinBox;scale_->setObjectName("instrumentScale");scale_->setDecimals(3);scale_->setRange(.001,1000);scale_->setValue(2);scale_->setSuffix(" V/div");controls->addWidget(scale_);
    freeze_=new QCheckBox(Language::text("Einfrieren"));freeze_->setObjectName("instrumentFreeze");controls->addWidget(freeze_);auto* save=new QPushButton("CSV");controls->addWidget(save);layout->addLayout(controls);auto* advanced=new QGridLayout;triggerMode_=new QComboBox;triggerMode_->setObjectName("triggerMode");triggerMode_->addItems({Language::text("Freilauf"),"Auto","Normal","Single"});advanced->addWidget(triggerMode_,0,0);triggerChannel_=new QComboBox;triggerChannel_->setObjectName("triggerChannel");triggerChannel_->setAccessibleName(Language::text("Triggerkanal"));triggerChannel_->addItems({"A / D0","B / D1"});advanced->addWidget(triggerChannel_,2,0);edge_=new QComboBox;edge_->addItems({Language::text("Steigende Flanke"),Language::text("Fallende Flanke")});advanced->addWidget(edge_,0,1);triggerLevel_=new QDoubleSpinBox;triggerLevel_->setRange(-100,100);triggerLevel_->setValue(2.5);triggerLevel_->setSuffix(" V");advanced->addWidget(triggerLevel_,0,2);auto* arm=new QPushButton(Language::text("Bereit"));advanced->addWidget(arm,0,3);math_=new QCheckBox("A − B");math_->setObjectName("scopeMath");advanced->addWidget(math_,0,4);decoder_=new QComboBox;decoder_->setObjectName("protocolDecoder");decoder_->addItems({Language::text("Kein Decoder"),"UART D0 (8N1)","SPI D0=CLK D1=DATA (↑ MSB)","I²C D0=SCL D1=SDA",Language::text("Protokollansicht (Modell)")});advanced->addWidget(decoder_,1,0,1,3);baud_=new QDoubleSpinBox;baud_->setObjectName("decoderBaud");baud_->setDecimals(0);baud_->setRange(1,2000000);baud_->setValue(9600);baud_->setSuffix(" baud");advanced->addWidget(baud_,1,3);auto* png=new QPushButton("PNG");advanced->addWidget(png,1,4);layout->addLayout(advanced);layout->addStretch(1);reading_=new QLabel;reading_->setWordWrap(true);reading_->setMaximumHeight(120);reading_->setTextInteractionFlags(Qt::TextSelectableByMouse|Qt::TextSelectableByKeyboard);layout->addWidget(reading_);
    auto rearm=[this]{triggerAt_.reset();captured_.clear();freeze_->setChecked(false);update();};connect(arm,&QPushButton::clicked,this,rearm);connect(triggerMode_,qOverload<int>(&QComboBox::currentIndexChanged),this,rearm);connect(edge_,qOverload<int>(&QComboBox::currentIndexChanged),this,rearm);connect(triggerChannel_,qOverload<int>(&QComboBox::currentIndexChanged),this,rearm);connect(triggerLevel_,qOverload<double>(&QDoubleSpinBox::valueChanged),this,rearm);connect(math_,&QCheckBox::toggled,this,[this]{refresh();});connect(decoder_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{refresh();});connect(baud_,qOverload<double>(&QDoubleSpinBox::valueChanged),this,[this]{refresh();});connect(png,&QPushButton::clicked,this,[this]{auto path=QFileDialog::getSaveFileName(this,Language::text("Messansicht speichern"),"measurement.png","PNG (*.png)");if(!path.isEmpty()&&!grab().save(path))QMessageBox::warning(this,"PNG",Language::text("Bild konnte nicht gespeichert werden."));});
