const InstrumentPanel::Trace* InstrumentPanel::trace()const{auto it=traces_.find(selection_->currentData().toString().toStdString());return it==traces_.end()?nullptr:&it->second;}
const std::deque<InstrumentSample>& InstrumentPanel::samples(const std::string& id)const{static const std::deque<InstrumentSample> empty;auto it=traces_.find(id);return it==traces_.end()?empty:it->second.buffer.samples();}
const std::deque<InstrumentSample>& InstrumentPanel::visible()const{static const std::deque<InstrumentSample> empty;return freeze_->isChecked()?frozen_:triggerMode_->currentIndex()>0&&!captured_.empty()?captured_:triggerMode_->currentIndex()==2?empty:trace()?trace()->buffer.samples():empty;}
void InstrumentPanel::configure(const CircuitDocument& document){
    const auto id=selection_->currentData();QSignalBlocker block(selection_);selection_->clear();std::set<std::string> ids;
    for(const auto& part:document.parts())if(instrument(part.kind)){ids.insert(part.id);auto [it,inserted]=traces_.try_emplace(part.id,Trace{part,measurement::TraceStore{}});it->second.part=part;selection_->addItem(Language::text(QString::fromStdString(componentSpec(part.kind).label))+" · "+QString::fromStdString(part.id),QString::fromStdString(part.id));}
    std::erase_if(traces_,[&](const auto& item){return !ids.contains(item.first);});selection_->setCurrentIndex(std::max(0,selection_->findData(id)));selected();
}
void InstrumentPanel::selectInstrument(const std::string& id){const int index=selection_->findData(QString::fromStdString(id));if(index>=0)selection_->setCurrentIndex(index);}
void InstrumentPanel::selected(){triggerAt_.reset();captured_.clear();cursorA_.reset();cursorB_.reset();freeze_->setChecked(false);if(auto* t=trace()){scale_->setSuffix(t->part.kind==PartKind::CurrentProbe?" A/div":" V/div");scale_->setValue(t->part.kind==PartKind::CurrentProbe?.002:2);scale_->setEnabled(t->part.kind!=PartKind::LogicAnalyzer);triggerLevel_->setEnabled(t->part.kind!=PartKind::LogicAnalyzer);{QSignalBlocker block(triggerChannel_);const int selected=triggerChannel_->currentIndex();triggerChannel_->clear();if(t->part.kind==PartKind::LogicAnalyzer){for(int i=0;i<8;++i)triggerChannel_->addItem("D"+QString::number(i));}else if(t->part.kind==PartKind::CurrentProbe)triggerChannel_->addItem("I");else triggerChannel_->addItems({"A","B"});triggerChannel_->setCurrentIndex(std::clamp(selected,0,triggerChannel_->count()-1));}if(t->part.kind==PartKind::Oscilloscope)timebase_->setValue(t->part.value);}refresh();}
void InstrumentPanel::reset(){for(auto& [id,t]:traces_)t.buffer.clear();freeze_->setChecked(false);frozen_.clear();captured_.clear();triggerAt_.reset();refresh();}
void InstrumentPanel::sample(Microseconds time,const CircuitState& state){
    for(auto& [id,t]:traces_){InstrumentSample point{time,{}};
        point=measurement::acquire(t.part,time,state);
        if(trace()==&t&&triggerMode_->currentIndex()>0&&!freeze_->isChecked()&&!t.buffer.samples().empty()){bool edge=measurement::crossed(t.buffer.samples().back(),point,std::size_t(triggerChannel_->currentIndex()),t.part.kind==PartKind::LogicAnalyzer?.5:triggerLevel_->value(),edge_->currentIndex()==0);if(edge&&!triggerAt_)triggerAt_=time;}
        t.buffer.append(std::move(point));
        if(trace()==&t&&triggerAt_&&double(time)>=*triggerAt_+timebase_->value()*5000){const double begin=double(*triggerAt_)-timebase_->value()*5000;captured_.clear();for(const auto& p:t.buffer.samples())if(double(p.time)>=begin)captured_.push_back(p);triggerAt_.reset();if(triggerMode_->currentIndex()==3){freeze_->setChecked(true);frozen_=captured_;}}
    }
}
bool InstrumentPanel::protocolView()const{return decoder_->currentIndex()==4;}
QByteArray InstrumentPanel::csv()const{auto* t=trace();if(!t)return "time_s\n";std::vector<std::string> columns;const int n=t->part.kind==PartKind::LogicAnalyzer?8:t->part.kind==PartKind::CurrentProbe?1:2;for(int i=0;i<n;++i)columns.push_back(t->part.kind==PartKind::LogicAnalyzer?"D"+std::to_string(i):t->part.kind==PartKind::CurrentProbe?"current_A":i?"B_V":"A_V");return QByteArray::fromStdString(measurement::csv(visible(),columns));}

void InstrumentPanel::refresh(){auto* t=trace();QString text=t?Language::text("Keine Messdaten. Simulation starten."):Language::text("Oszilloskop, Logikanalysator oder Stromsonde zur Schaltung hinzufügen.");const auto& data=visible();if(t&&!data.empty()){text=QString("t = %1 ms  ").arg(data.back().time/1000.0,0,'f',3);int i=0;for(const auto& v:data.back().channels){text+=QString("%1: %2  ").arg(t->part.kind==PartKind::CurrentProbe?"I":t->part.kind==PartKind::LogicAnalyzer?"D"+QString::number(i):i?"B":"A").arg(v?QString::number(*v,'g',5):"Z");++i;}if(t->part.kind==PartKind::LogicAnalyzer)text+=QString(" ≥ %1 V = HIGH").arg(t->part.value);}if(t&&!data.empty()){
        std::vector<TimedValue> a,b;for(const auto& point:data){a.push_back({point.time*1e-6,point.channels[0]});if(point.channels.size()>1)b.push_back({point.time*1e-6,point.channels[1]});}auto m=measure(a);text+=QString("\nA: min %1 · max %2 · pp %3 · RMS %4").arg(m.minimum,0,'g',4).arg(m.maximum,0,'g',4).arg(m.maximum-m.minimum,0,'g',4).arg(m.rms,0,'g',4);if(m.frequency)text+=QString(" · %1 Hz").arg(*m.frequency,0,'g',5);if(m.duty)text+=QString(" · %1 %").arg(*m.duty*100,0,'f',1);
        if(cursorA_&&cursorB_){double delta=std::abs(*cursorB_-*cursorA_);text+=QString("\nΔt = %1 ms").arg(delta/1000,0,'g',5);if(delta>0)text+=QString(" · 1/Δt = %1 Hz").arg(1e6/delta,0,'g',5);auto cursorValue=[&](double time)->std::optional<double>{if(data.empty()||time<data.front().time||time>data.back().time)return {};std::optional<double> value;for(const auto& point:data){if(point.time>time)break;value=point.channels[0];}return value;};auto a=cursorValue(*cursorA_),b=cursorValue(*cursorB_);if(a&&b)text+=QString(" · ΔA = %1").arg(*b-*a,0,'g',5);}
        if(t->part.kind==PartKind::LogicAnalyzer&&decoder_->currentIndex()>0&&decoder_->currentIndex()<4){std::vector<DecodedByte> decoded;if(decoder_->currentIndex()==1)decoded=decodeUart(a,unsigned(baud_->value()));else if(decoder_->currentIndex()==2)decoded=decodeSpi(a,b);else decoded=decodeI2c(a,b);text+="\n"+decoder_->currentText()+": ";const auto start=decoded.size()>8?decoded.size()-8:0;for(auto i=start;i<decoded.size();++i)text+=QString("%1%2 ").arg(decoded[i].value,2,16,QChar('0')).arg(decoded[i].valid?"":"!");}
    }if(t&&t->buffer.overwritten())text+="\n"+Language::text("Älteste Messpunkte überschrieben: %1").arg(t->buffer.overwritten());if(protocolView()&&traffic_){text+="\n"+Language::text("Modellierte Transaktionen; keine gemessenen Busflanken.");const auto& entries=traffic_->entries();auto first=entries.size()>8?entries.size()-8:0;for(auto i=first;i<entries.size();++i){const auto& e=entries[i];text+=QString("\n%1 µs · %2 · %3 · %4 · %5").arg(e.time).arg(QString::fromStdString(e.board),QString::fromStdString(e.bus),QString::fromStdString(e.target),QString::fromStdString(e.status));}}reading_->setText(text);reading_->setToolTip(text);update();}
void InstrumentPanel::paintEvent(QPaintEvent*){QPainter p(this);QRectF plot(46,114,width()-60,height()-212);if(plot.width()<=0||plot.height()<=0)return;p.fillRect(plot,QColor("#101c29"));p.setPen(QPen(QColor("#2c3a4b"),1));for(int i=0;i<=10;++i){double x=plot.left()+plot.width()*i/10;p.drawLine(QPointF(x,plot.top()),QPointF(x,plot.bottom()));}for(int i=0;i<=8;++i){double y=plot.top()+plot.height()*i/8;p.drawLine(QPointF(plot.left(),y),QPointF(plot.right(),y));}
    const auto* t=trace();const auto& data=visible();if(!t||data.empty())return;const double span=timebase_->value()*10000,end=data.back().time,begin=end-span;const bool logic=t->part.kind==PartKind::LogicAnalyzer;const QColor colors[]={QColor("#facc15"),QColor("#38bdf8"),QColor("#f472b6"),QColor("#4ade80")};
    p.save();p.setClipRect(plot);for(std::size_t channel=0;channel<data.back().channels.size()+((math_->isChecked()&&!logic&&data.back().channels.size()==2)?1:0);++channel){QPainterPath path;bool connected=false;double previousY=0;for(const auto& point:data){if(point.time<begin){connected=false;continue;}auto value=channel<point.channels.size()?point.channels[channel]:point.channels[0]&&point.channels[1]?std::optional<double>(*point.channels[0]-*point.channels[1]):std::nullopt;if(!value){connected=false;continue;}double x=plot.left()+(point.time-begin)/span*plot.width(),v=*value,y=logic?plot.top()+(channel+.7-.45*v)*plot.height()/8:plot.center().y()-v/scale_->value()*plot.height()/8;if(!connected)path.moveTo(x,y);else{if(logic)path.lineTo(x,previousY);path.lineTo(x,y);}previousY=y;connected=true;}p.setPen(QPen(colors[channel%4],1.5));p.drawPath(path);}for(auto cursor:{cursorA_,cursorB_})if(cursor){double x=plot.left()+(*cursor-begin)/span*plot.width();p.setPen(QPen(QColor("#e2e8f0"),1,Qt::DashLine));p.drawLine(QPointF(x,plot.top()),QPointF(x,plot.bottom()));}p.restore();p.setPen(palette().color(QPalette::Text));p.drawText(QRectF(0,plot.center().y()-10,43,20),Qt::AlignRight|Qt::AlignVCenter,"0");p.drawText(QRectF(plot.left(),plot.bottom()+2,plot.width(),18),Qt::AlignRight,QString("%1 ms").arg(end/1000,0,'f',2));
}

void InstrumentPanel::mousePressEvent(QMouseEvent* event){QRectF plot(46,114,width()-60,height()-212);if(plot.contains(event->position())&&!visible().empty()){double end=visible().back().time,span=timebase_->value()*10000;double time=end-span+(event->position().x()-plot.left())/plot.width()*span;if(nextCursorB_)cursorB_=time;else cursorA_=time;nextCursorB_=!nextCursorB_;refresh();event->accept();return;}QWidget::mousePressEvent(event);}
